<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Personal Expense Tracker</title>
  <style>
    * { box-sizing: border-box; }
    body {
      font-family: system-ui, sans-serif;
      max-width: 720px;
      margin: 0 auto;
      padding: 16px;
      color: #222;
      background: #f6f7f8;
    }
    h1 { font-size: 1.4rem; margin: 0 0 16px; }
    h2 { font-size: 1.05rem; margin: 20px 0 8px; }
    section {
      background: #fff;
      border: 1px solid #ddd;
      border-radius: 6px;
      padding: 12px;
      margin-bottom: 12px;
    }
    label { display: block; font-size: 0.85rem; margin-bottom: 4px; }
    .row { display: flex; flex-wrap: wrap; gap: 10px; align-items: flex-end; }
    .field { flex: 1 1 120px; min-width: 110px; }
    input, select, button {
      width: 100%;
      padding: 7px 8px;
      font: inherit;
      border: 1px solid #bbb;
      border-radius: 4px;
    }
    button {
      cursor: pointer;
      background: #1a5fb4;
      color: #fff;
      border-color: #1a5fb4;
    }
    button:hover { background: #15539c; }
    #add-expense { width: auto; min-width: 120px; }
    #form-error { color: #b00020; min-height: 1.2em; margin-top: 8px; font-size: 0.9rem; }
    .summary-line { font-size: 1.15rem; margin-bottom: 8px; }
    #total { font-weight: 700; }
    .cat-totals { display: flex; flex-wrap: wrap; gap: 8px; }
    .cat-total {
      background: #eef2f6;
      border-radius: 4px;
      padding: 6px 10px;
      font-size: 0.9rem;
    }
    .expense {
      display: flex;
      flex-wrap: wrap;
      gap: 8px;
      align-items: center;
      padding: 8px 0;
      border-bottom: 1px solid #eee;
    }
    .expense span { margin-right: 6px; }
    .exp-amount { font-weight: 600; min-width: 72px; }
    .exp-category { text-transform: capitalize; min-width: 90px; }
    .exp-date { color: #555; }
    .exp-note { color: #666; flex: 1 1 120px; font-size: 0.9rem; }
    .exp-del {
      width: auto;
      background: #c01c28;
      border-color: #c01c28;
      padding: 4px 10px;
      font-size: 0.85rem;
    }
    .exp-del:hover { background: #a01520; }
    #expense-list:empty::after { content: "No expenses yet."; color: #777; }
  </style>
</head>
<body>
  <h1>Personal Expense Tracker</h1>

  <section>
    <h2>Add expense</h2>
    <form id="expense-form">
      <div class="row">
        <div class="field">
          <label for="amount">Amount</label>
          <input type="number" id="amount" step="0.01" placeholder="0.00">
        </div>
        <div class="field">
          <label for="category">Category</label>
          <select id="category">
            <option value="groceries">groceries</option>
            <option value="transport">transport</option>
            <option value="bills">bills</option>
            <option value="fun">fun</option>
          </select>
        </div>
        <div class="field">
          <label for="date">Date</label>
          <input type="date" id="date">
        </div>
        <div class="field">
          <label for="note">Note (optional)</label>
          <input type="text" id="note" placeholder="optional">
        </div>
        <div class="field" style="flex: 0 0 auto;">
          <button type="submit" id="add-expense">Add expense</button>
        </div>
      </div>
      <div id="form-error"></div>
    </form>
  </section>

  <section>
    <h2>Filters</h2>
    <div class="row">
      <div class="field">
        <label for="filter-category">Category</label>
        <select id="filter-category">
          <option value="all">all</option>
          <option value="groceries">groceries</option>
          <option value="transport">transport</option>
          <option value="bills">bills</option>
          <option value="fun">fun</option>
        </select>
      </div>
      <div class="field">
        <label for="filter-from">From</label>
        <input type="date" id="filter-from">
      </div>
      <div class="field">
        <label for="filter-to">To</label>
        <input type="date" id="filter-to">
      </div>
    </div>
  </section>

  <section>
    <h2>Summary</h2>
    <div class="summary-line">Total: <span id="total">0.00</span></div>
    <div class="cat-totals">
      <div class="cat-total" data-cat="groceries">groceries: 0.00</div>
      <div class="cat-total" data-cat="transport">transport: 0.00</div>
      <div class="cat-total" data-cat="bills">bills: 0.00</div>
      <div class="cat-total" data-cat="fun">fun: 0.00</div>
    </div>
  </section>

  <section>
    <h2>Expenses</h2>
    <div id="expense-list"></div>
  </section>

  <script>
    (function () {
      var STORAGE_KEY = 'expenses';
      var CATEGORIES = ['groceries', 'transport', 'bills', 'fun'];
      var expenses = [];

      var amountEl = document.getElementById('amount');
      var categoryEl = document.getElementById('category');
      var dateEl = document.getElementById('date');
      var noteEl = document.getElementById('note');
      var formError = document.getElementById('form-error');
      var form = document.getElementById('expense-form');
      var listEl = document.getElementById('expense-list');
      var totalEl = document.getElementById('total');
      var filterCat = document.getElementById('filter-category');
      var filterFrom = document.getElementById('filter-from');
      var filterTo = document.getElementById('filter-to');

      function load() {
        try {
          var raw = localStorage.getItem(STORAGE_KEY);
          expenses = raw ? JSON.parse(raw) : [];
          if (!Array.isArray(expenses)) expenses = [];
        } catch (e) {
          expenses = [];
        }
      }

      function save() {
        localStorage.setItem(STORAGE_KEY, JSON.stringify(expenses));
      }

      function isVisible(exp) {
        var cat = filterCat.value;
        var from = filterFrom.value;
        var to = filterTo.value;
        if (cat && cat !== 'all' && exp.category !== cat) return false;
        if (from && exp.date < from) return false;
        if (to && exp.date > to) return false;
        return true;
      }

      function updateTotals() {
        var visible = expenses.filter(isVisible);
        var sum = 0;
        var i;
        for (i = 0; i < visible.length; i++) sum += Number(visible[i].amount);
        totalEl.textContent = sum.toFixed(2);

        for (i = 0; i < CATEGORIES.length; i++) {
          var cat = CATEGORIES[i];
          var catSum = 0;
          for (var j = 0; j < visible.length; j++) {
            if (visible[j].category === cat) catSum += Number(visible[j].amount);
          }
          var el = document.querySelector('.cat-total[data-cat="' + cat + '"]');
          if (el) el.textContent = cat + ': ' + catSum.toFixed(2);
        }
      }

      function applyFilters() {
        var rows = listEl.querySelectorAll('.expense');
        for (var i = 0; i < rows.length; i++) {
          var row = rows[i];
          var exp = {
            category: row.getAttribute('data-category'),
            date: row.getAttribute('data-date')
          };
          row.style.display = isVisible(exp) ? '' : 'none';
        }
        updateTotals();
      }

      function render() {
        listEl.innerHTML = '';
        for (var i = 0; i < expenses.length; i++) {
          (function (exp) {
            var row = document.createElement('div');
            row.className = 'expense';
            row.setAttribute('data-id', exp.id);
            row.setAttribute('data-category', exp.category);
            row.setAttribute('data-date', exp.date);
            if (!isVisible(exp)) row.style.display = 'none';

            var amt = document.createElement('span');
            amt.className = 'exp-amount';
            amt.textContent = Number(exp.amount).toFixed(2);

            var cat = document.createElement('span');
            cat.className = 'exp-category';
            cat.textContent = exp.category;

            var dt = document.createElement('span');
            dt.className = 'exp-date';
            dt.textContent = exp.date;

            var note = document.createElement('span');
            note.className = 'exp-note';
            note.textContent = exp.note || '';

            var del = document.createElement('button');
            del.type = 'button';
            del.className = 'exp-del';
            del.textContent = 'Delete';
            del.addEventListener('click', function () {
              expenses = expenses.filter(function (e) { return e.id !== exp.id; });
              save();
              render();
            });

            row.appendChild(amt);
            row.appendChild(cat);
            row.appendChild(dt);
            row.appendChild(note);
            row.appendChild(del);
            listEl.appendChild(row);
          })(expenses[i]);
        }
        updateTotals();
      }

      function addExpense(e) {
        if (e) e.preventDefault();
        var raw = amountEl.value;
        var amount = parseFloat(raw);

        if (raw === '' || raw === null || String(raw).trim() === '' || isNaN(amount) || !isFinite(amount) || amount <= 0) {
          formError.textContent = 'Enter a valid amount greater than zero.';
          return;
        }
        if (!dateEl.value) {
          formError.textContent = 'Please select a date.';
          return;
        }

        formError.textContent = '';
        expenses.unshift({
          id: Date.now().toString(36) + Math.random().toString(36).slice(2),
          amount: amount,
          category: categoryEl.value,
          date: dateEl.value,
          note: (noteEl.value || '').trim()
        });
        save();
        amountEl.value = '';
        render();
      }

      form.addEventListener('submit', addExpense);
      document.getElementById('add-expense').addEventListener('click', function (e) {
        e.preventDefault();
        addExpense(e);
      });

      filterCat.addEventListener('change', applyFilters);
      filterFrom.addEventListener('change', applyFilters);
      filterTo.addEventListener('change', applyFilters);
      filterFrom.addEventListener('input', applyFilters);
      filterTo.addEventListener('input', applyFilters);

      load();
      if (!dateEl.value) {
        var today = new Date();
        var y = today.getFullYear();
        var m = String(today.getMonth() + 1).padStart(2, '0');
        var d = String(today.getDate()).padStart(2, '0');
        dateEl.value = y + '-' + m + '-' + d;
      }
      render();
    })();
  </script>
</body>
</html>
